{
  "status": "SUPPORTED",
  "task_summary": "Find hardware, fasten two parts together on a table, and return the tool.",
  "task_contract": {
    "functional_roles": [
      {
        "id": "fastener",
        "entity_kind": "OBJECT",
        "function": "Provides the mechanical connection to hold parts together",
        "required_count": 1,
        "binding_policy": "REUSABLE"
      ,
        "candidate_categories": ["screw", "bolt", "nut", "pin"],
        "required_properties": ["rigid", "threaded_or_friction_fit"]
      },
      {
        "id": "part",
        "entity_kind": "OBJECT",
        "function": "The object(s) to be joined by the fastener",
        "required_count": 2,
        "binding_policy": "DISTINCT"
      ,
        "candidate_categories": ["block", "plate", "metal_piece"],
        "required_properties": ["has_hole_or_slot", "receives_fastener"]
      },
      {
        "id": "tool",
        "entity_kind": "OBJECT",
        "function": "The implement used to manipulate the fastener",
        "required_count": 1,
        "binding_policy": "REUSABLE"
      ,
        "candidate_categories": ["screwdriver", "wrench", "claw"],
        "required_properties": ["gripping_end", "applies_force"]
      },
      {
        "id": "workbench_surface",
        "entity_kind": "REGION",
        "function": "The location where the fastening takes place",
        "required_count": 1,
        "binding_policy": "SHARED"
      ,
        "candidate_categories": ["table", "desk", "bench"],
        "required_properties": ["flat_surface", "supports_objects"]
      }
    ],
    "functional_relations": [
      {
        "id": "connection",
        "relation": "Fastener connects Part A to Part B",
        "participant_roles": ["part", "fastener", "part"]
      ,
        "required": true
      }
    ],
    "operation_pairings": [
      {
        "id": "fasten_operation",
        "operation": "Secure the fastener between the two parts using the tool",
        "participant_roles": ["tool", "fastener", "part", "part"]
      ,
        "operation_count": 1
      },
      {
        "id": "return_tool_operation",
        "operation": "Place the tool on the workbench surface",
        "participant_roles": ["tool", "workbench_surface"]
      ,
        "operation_count": 1
      }
    ]
  },
  "observation_guidance": {
    "visible_candidates_per_role": {
      "fastener": [],
      "part": [],
      "tool": [
        {
          "label": "yellow_blue_object_on_tray",
          "visual_description": "Yellow handle with blue block on a black tray"
        }
      ],
      "workbench_surface": [
        {
          "label": "wooden_table_top",
          "visual_description": "Wooden table surface"
        }
      ]
    },
    "inspectable_regions": [
      {
        "id": "left_drawer",
        "label": "Left drawer under table",
        "visual_description": "Blue drawer with handle",
        "reason": "Closed storage structure, likely contains hardware"
      },
      {
        "id": "right_drawer",
        "label": "Right drawer under table",
        "visual_description": "Blue drawer with handle",
        "reason": "Closed storage structure, likely contains hardware"
      },
      {
        "id": "cabinet",
        "label": "Cabinet on table",
        "visual_description": "Blue cabinet with door",
        "reason": "Closed storage structure, likely contains hardware"
      }
    ],
    "inspection_order": [
      "left_drawer",
      "right_drawer",
      "cabinet"
    ]
  }
  ,
  "unsupported_reason": ""
  ,
  "schema_version": 3
}
